UPDATE profile_user_label
SET label_value = #{labelValue,jdbcType=VARCHAR}
WHERE user_id = #{userId,jdbcType=VARCHAR}
  AND label_id = #{labelId,jdbcType=VARCHAR}

UPDATE profile_user_label
SET sort_order = CASE label_id

        WHEN (SELECT l.label_id FROM profile_meta_label l
              WHERE l.label_category_id = #{categoryId}
              AND l.label_id IN (SELECT ul2.label_id FROM profile_user_label ul2
                                 WHERE ul2.user_id = #{userId} AND ul2.label_id = l.label_id)
              LIMIT 1) THEN #{index}

END
WHERE user_id = #{userId}
AND label_id IN (
    SELECT l2.label_id FROM profile_meta_label l2
    WHERE l2.label_category_id IN

        #{cid}

)

